def semver_sort(versions):
    def parse_version(v):
        # Split off build metadata (everything after '+')
        if '+' in v:
            version_part, build = v.rsplit('+', 1)
        else:
            version_part = v

        # Split off pre-release (everything after '-')
        if '-' in version_part:
            core_part, prerelease = version_part.split('-', 1)
        else:
            core_part = version_part
            prerelease = None

        # Parse MAJOR.MINOR.PATCH
        parts = core_part.split('.')
        major = int(parts[0])
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease:
            prerelease_ids = prerelease.split('.')
        else:
            prerelease_ids = None

        return (major, minor, patch, prerelease_ids)

    def prerelease_sort_key(prerelease_ids):
        if prerelease_ids is None:
            # No pre-release sorts after pre-release
            return (1, [])

        # Convert each identifier for comparison
        converted = []
        for identifier in prerelease_ids:
            if identifier.isdigit():
                # All-digit identifiers sort numerically and before non-digit
                converted.append((0, int(identifier)))
            else:
                # Non-digit identifiers sort by ASCII order
                converted.append((1, identifier))

        return (0, converted)

    def sort_key(item):
        index, version = item
        major, minor, patch, prerelease_ids = parse_version(version)
        prerel_key = prerelease_sort_key(prerelease_ids)
        # Return tuple for sorting: (major, minor, patch, prerel_key, index for stable sort)
        return (major, minor, patch, prerel_key, index)

    # Create list of (original_index, version) to maintain stable sort
    indexed_versions = list(enumerate(versions))
    # Sort by the sort key
    sorted_versions = sorted(indexed_versions, key=sort_key)
    # Extract just the version strings
    return [version for _, version in sorted_versions]

